let lang='en';const switcher=document.getElementById('language');function setLanguage(next){lang=next;document.documentElement.lang=next==='zh'?'zh-CN':'en';document.querySelectorAll('[data-en]').forEach(el=>{el.innerHTML=el.dataset[next]});switcher.textContent=next==='en'?'中文':'English';switcher.setAttribute('aria-label',next==='en'?'Switch to Chinese':'Switch to English');document.title=next==='en'?'AirNest | Sydney Property Services':'AirNest | 悉尼房屋清洁与维修';}switcher.addEventListener('click',()=>setLanguage(lang==='en'?'zh':'en'));document.getElementById('year').textContent=new Date().getFullYear();

const menuButton=document.getElementById('menu-toggle'),menu=document.getElementById('main-menu');function closeMenu(){menu.hidden=true;menuButton.setAttribute('aria-expanded','false');menuButton.setAttribute('aria-label','Open menu');}menuButton.addEventListener('click',()=>{const open=menuButton.getAttribute('aria-expanded')!=='true';menu.hidden=!open;menuButton.setAttribute('aria-expanded',String(open));menuButton.setAttribute('aria-label',open?'Close menu':'Open menu');});menu.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu();menuButton.focus();}});
